module x_oracle::user_oracle;

use sui::clock::Clock;
use std::type_name::TypeName;

use pyth::price_info::PriceInfoObject;
use math::float::{Self, Decimal};

use x_oracle::x_oracle::{Self, XOracle, BaseToken};
use x_oracle::oracle_error;
use x_oracle::price_feed::{Self, PriceFeedComponent};

// refresh pyth price feed, note that we are updating against usd prices
public fun refresh_usd_price<CoinType>(
    x_oracle: &mut XOracle,
    price_info_object: &PriceInfoObject,
    clock: &Clock,
) {
    x_oracle.ensure_version_matches();

    x_oracle::refresh_usd_price<CoinType>(x_oracle, price_info_object, clock)
}


/// Get the default price value, which is ema, for general use
public fun get_price(x_oracle: &XOracle, type_name: TypeName, base_token: BaseToken, clock: &Clock): Decimal {
    x_oracle.ensure_version_matches();

    let ema = x_oracle.price(type_name, base_token).ema();
    check_price(ema, x_oracle.price_delay_tolerance_ms(), clock)
}

/// Get the spot price value
public fun get_spot_price(x_oracle: &XOracle, type_name: TypeName, base_token: BaseToken, clock: &Clock): Decimal {
    x_oracle.ensure_version_matches();

    let spot = x_oracle.price(type_name, base_token).spot();
    check_price(spot, x_oracle.price_delay_tolerance_ms(), clock)
}

/// This method checks that ema and spot price are within max_diff_allowed
public fun get_price_with_check(x_oracle: &XOracle, type_name: TypeName, base_token: BaseToken, clock: &Clock, max_diff_allowed: Decimal): Decimal {
    x_oracle.ensure_version_matches();

    let price_feed =  x_oracle.price(type_name, base_token);

    let ema_price_value = check_price(price_feed.ema(), x_oracle.price_delay_tolerance_ms(), clock);
    let spot_price_value = check_price(price_feed.spot(), x_oracle.price_delay_tolerance_ms(), clock);

    let abs_diff = if (ema_price_value.gt(spot_price_value)) {
        ema_price_value.sub(spot_price_value).div(spot_price_value)
    } else {
        spot_price_value.sub(ema_price_value).div(spot_price_value)
    };

    assert!(abs_diff.le(max_diff_allowed), oracle_error::ema_spot_price_too_different());

    ema_price_value
}

fun check_price(price_feed_component: &PriceFeedComponent, price_delay_tolerance_ms: u64, clock: &Clock): Decimal {
    let price_value = price_feed_component.value();
    assert!(price_value > 0, oracle_error::oracle_zero_price_error());

    let last_updated = price_feed_component.update_time();
    let age = clock.timestamp_ms() - last_updated * 1000;
    assert!(age <= price_delay_tolerance_ms, oracle_error::oracle_stale_price_error());

    float::from_quotient(price_value, 10u64.pow(price_feed::decimals()))
}

